import{_ as t,c as e,o as n,a4 as a}from"./chunks/framework.DZlzUqxb.js";const b=JSON.parse('{"title":"AI资讯日报 2026/3/2","description":"特朗普封杀Anthropic，Claude反登App Store榜首，美军中东实战使用Claude AI加速写码但工程管理更难，vibe coding堆积技术债，初级开发者沦为AI搬运工 Nano Banana 2视觉能力超预期，Cursor进入云端智能体时代，Codex周活破160万 复旦Gene","frontmatter":{"linkTitle":"03-02 AI资讯","title":"AI资讯日报 2026/3/2","weight":30,"breadcrumbs":false,"comments":true,"description":"特朗普封杀Anthropic，Claude反登App Store榜首，美军中东实战使用Claude AI加速写码但工程管理更难，vibe coding堆积技术债，初级开发者沦为AI搬运工 Nano Banana 2视觉能力超预期，Cursor进入云端智能体时代，Codex周活破160万 复旦Gene"},"headers":[],"relativePath":"AI/daily/cn/2026-03/2026-03-02.md","filePath":"AI/daily/cn/2026-03/2026-03-02.md","lastUpdated":1773574286000}'),s={name:"AI/daily/cn/2026-03/2026-03-02.md"};function o(g,r,l,i,p,d){return n(),e("div",null,[...r[0]||(r[0]=[a(`<h1 align="center">2026-03-02 AI资讯</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>特朗普封杀Anthropic，Claude反登App Store榜首，美军中东实战使用Claude</span></span>
<span class="line"><span>AI加速写码但工程管理更难，vibe coding堆积技术债，初级开发者沦为AI搬运工</span></span>
<span class="line"><span>Nano Banana 2视觉能力超预期，Cursor进入云端智能体时代，Codex周活破160万</span></span>
<span class="line"><span>复旦GenericAgent自主操控微信，WiFi信号实现人体姿态感知，阿里开源AI沙箱</span></span>
<span class="line"><span>Claude Code团队推Git并行开发法，Prompt缓存成本降至十分之一，多Agent协作成趋势</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="产品与功能更新" tabindex="-1">产品与功能更新 <a class="header-anchor" href="#产品与功能更新" aria-label="Permalink to &quot;产品与功能更新&quot;">​</a></h3><ol><li><p><strong>Nano Banana 2视觉能力炸裂登场。</strong> 随手拍张📸唱机照片就能出<a href="https://x.com/oran_ge/status/2027909052215484579" target="_blank" rel="noreferrer">精美设计图(AI资讯)</a>。<strong>Nano Banana 2</strong>🚀某些方面明显比Pro强。很多人(✧∀✧)小看它当蒸馏模型。实测<strong>视觉设计</strong>🎨水平逆天。好消息是没火所以🔥算力不紧张。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kjp3svxzf68vtwb576c26x98.avif" alt="AI资讯：Nano Banana 2将普通唱机照片转化为高级视觉设计产品图" loading="lazy"><br></p></li><li><p><strong>Cursor宣布进入AI开发第三时代。</strong> Cursor创始人🚀<a href="https://x.com/oran_ge/status/2027913185593000358" target="_blank" rel="noreferrer">披露内部激进探索(AI资讯)</a>方向。<strong>云端智能体</strong>与代码制品(✧∀✧)成为核心。虽然大家吐槽它不酷了💡。但Cloud agents架构🔥变革意义深远。<strong>AI编程</strong>范式正在被重新定义。</p></li><li><p><strong>Codex周活用户翻倍突破160万。</strong><strong>Codex</strong>周活🚀自年初<a href="https://x.com/vista8/status/2028023198814769529" target="_blank" rel="noreferrer">增长逾两倍(AI资讯)</a>。紧追(✧∀✧)<strong>Claude Code</strong>势头凶猛。编程工具🔥竞争日趋白热化。用户虽然还是偏爱Claude💡。但这匹黑马的增速不容忽视。</p></li></ol><h3 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h3><ol><li><p><strong>复旦智能体学会发朋友圈了。</strong> 复旦<strong>A3实验室</strong>🚀发布<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;mid=2651018653&amp;idx=1&amp;sn=5d8578072edd5a01bd4f4fbfb20aadb8" target="_blank" rel="noreferrer">GenericAgent(AI资讯)</a>。这个数字生命(✧∀✧)自主学会操作微信。核心代码仅<strong>3000行</strong>💡极简到离谱。能自己🔥点奶茶还会整理记忆。手机电脑通吃的<strong>自进化</strong>架构太秀了。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kjp3t334f68vtwba881ppz4m.avif" alt="AI资讯：复旦GenericAgent自主操作微信朋友圈与好友互动截图" loading="lazy"><br></p></li><li><p><strong>OpenAI工程化框架宣告人类退场。</strong><a href="https://openai.com/index/harness-engineering/" target="_blank" rel="noreferrer">OpenAI最新博客(AI资讯)</a>揭示🚀<strong>自动进化</strong>闭环。Human in the loop反成🔥最大绊脚石。定好终点(✧∀✧)开到140迈自动驾驶。撞毁了带着<strong>日志重生</strong>💡继续跑。<strong>工程闭环</strong>让效能实现指数级飞跃。</p></li></ol><h3 id="行业展望与社会影响" tabindex="-1">行业展望与社会影响 <a class="header-anchor" href="#行业展望与社会影响" aria-label="Permalink to &quot;行业展望与社会影响&quot;">​</a></h3><ol><li><p><strong>Claude遭封杀反登顶App Store榜首。</strong> 特朗普下令🔥全面封杀Anthropic。Claude却一夜(✧∀✧)冲上<strong>美区榜首</strong>。全网掀起💪怒删ChatGPT运动。Dario Amodei含泪<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;mid=2652678869&amp;idx=1&amp;sn=be51587d9f1b0ada1a19e7bab063f310" target="_blank" rel="noreferrer">首度发声(AI资讯)</a>坚守红线。OpenAI趁机🚀拿下五角大楼<strong>国防大单</strong>。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kjp3t7mtf68vtwbgwptcajx4.avif" alt="AI资讯：Anthropic CEO达里奥·阿莫迪在CBS专访中神情疲惫地阐述公司红线立场" loading="lazy"><br></p></li><li><p><strong>美军中东实战竟动用了Claude模型。</strong> 华尔街日报🔥爆料<a href="https://x.com/Gorden_Sun/status/2027943715340488991" target="_blank" rel="noreferrer">美军使用Claude(AI资讯)</a>参与中东打击行动。禁令生效仅数小时⚡即投入实战。<strong>AI军事化</strong>进程(✧∀✧)超乎想象。现代战争格局🤖正在被彻底改写。民用模型秒变<strong>战场工具</strong>令人震惊。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kjp3tkjgf68vtwbswyvepj0s.avif" alt="AI资讯：华尔街日报关于美军在中东行动中使用Claude AI的报道截图" loading="lazy"><br></p></li><li><p><strong>AI写码提速但工程管理反而更难。</strong> LLM让🚀<strong>机械写码</strong>速度暴涨。但从想法到发布的<a href="https://newshacker.me/story?id=47206824" target="_blank" rel="noreferrer">总耗时并未缩短(AI资讯)</a>。<strong>Vibe coding</strong>疯狂堆砌💀技术债。工程师被迫(•̀ᴗ•́)و转型为<strong>架构审核者</strong>。掌握底层逻辑才是🔥核心竞争力。</p></li><li><p><strong>AI公司终将反制政府权力？</strong> Stability AI前CEO🚀<a href="https://x.com/EMostaque/status/2027912344823861677" target="_blank" rel="noreferrer">大胆预言(AI资讯)</a>令人深思。<strong>AI企业</strong>或比政府(✧∀✧)更强势。权力格局正在🔥被重新洗牌。民主社会何去何从💡引发激辩。这波<strong>技术政治</strong>博弈才刚刚开始。</p></li><li><p><strong>管理层逼用AI让初级开发成废人。</strong> 公司强推🚀<strong>AI使用率</strong>当绩效考核。初级开发者(╥_╥)照搬LLM输出不求甚解。<a href="https://newshacker.me/story?id=47206663" target="_blank" rel="noreferrer">深度分析(AI资讯)</a>指出风险巨大。必须<strong>自主验证</strong>🔥代码才能成长。没有实践就培养不出💡<strong>高级工程师</strong>。</p></li><li><p><strong>社区大逃亡：从ChatGPT迁移至Claude。</strong> 一条记忆导出🚀prompt引爆<a href="https://newshacker.me/story?id=47204571" target="_blank" rel="noreferrer">迁移浪潮(AI资讯)</a>。用户因<strong>伦理信任</strong>(ò_óˇ)问题纷纷出走。Claude的Opus 4.6回答更🔥简洁直接。但<strong>AGENTS.md</strong>配置标准尚未统一。跨平台💡无缝迁移仍需大量工程。</p></li></ol><h3 id="开源top项目" tabindex="-1">开源TOP项目 <a class="header-anchor" href="#开源top项目" aria-label="Permalink to &quot;开源TOP项目&quot;">​</a></h3><ol><li><p><strong>WiFi信号秒变人体姿态传感器。</strong><a href="https://github.com/ruvnet/wifi-densepose" target="_blank" rel="noreferrer">wifi-densepose(AI资讯)</a>⭐17.3k今日暴涨4500星。家用<strong>WiFi信号</strong>🚀直接估计人体姿态。告别摄像头(✧∀✧)保护隐私。还能🔥实时监测<strong>生命体征</strong>。穿墙感知能力简直太炸裂。</p></li><li><p><strong>阿里开源OpenSandbox通用AI沙箱。</strong><a href="https://github.com/alibaba/OpenSandbox" target="_blank" rel="noreferrer">OpenSandbox(AI资讯)</a>⭐3.3k今日狂飙🔥1179星。为<strong>AI智能体</strong>提供(✧∀✧)标准化执行环境。支持多语言SDK加💡<strong>Docker</strong>运行时。覆盖代码执行与<strong>GUI Agent</strong>全场景。统一API让🚀开发丝滑到飞起。</p></li><li><p><strong>ruflo打造Claude多智能体编排平台。</strong><a href="https://github.com/ruvnet/ruflo" target="_blank" rel="noreferrer">ruflo(AI资讯)</a>⭐17.3k专为🚀<strong>Claude</strong>生态设计。编排分布式(✧∀✧)<strong>多Agent集群</strong>协同作战。集成RAG与🔥<strong>Codex原生对接</strong>。企业级架构💡开箱即用。自动化工作流部署效率极高。</p></li><li><p><strong>阿里MobileAgent跨APP自主操控手机。</strong><a href="https://github.com/X-PLUG/MobileAgent" target="_blank" rel="noreferrer">MobileAgent(AI资讯)</a>⭐7.7k今日涨190星。依靠🚀<strong>多模态视觉</strong>感知屏幕内容。跨APP(✧∀✧)自主完成复杂操作链。<strong>阿里出品</strong>🔥将彻底解放用户双手。移动端智能体💡正在全面崛起。</p></li><li><p><strong>Superset：AI Agent时代的本地IDE。</strong><a href="https://github.com/superset-sh/superset" target="_blank" rel="noreferrer">Superset(AI资讯)</a>⭐2.9k今日涨389星。本地🚀同时运行<strong>Claude Code</strong>与Codex大军。高效调度(✧∀✧)多个AI模型协同编码。<strong>Agent原生</strong>💡开发环境正式上线。定义未来🔥编程工作站新形态。</p></li></ol><h3 id="社媒分享" tabindex="-1">社媒分享 <a class="header-anchor" href="#社媒分享" aria-label="Permalink to &quot;社媒分享&quot;">​</a></h3><ol><li><p><strong>Claude Code之父曝光养蛊式开发法。</strong> Boris团队🚀用<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;mid=2652678869&amp;idx=3&amp;sn=10ffee70b959f09ec3bf34a86ea40cf1" target="_blank" rel="noreferrer">Git Worktree(AI资讯)</a>拉3到5个并行会话。让两条Claude(✧∀✧)互相<strong>查岗审代码</strong>。<strong>Plan Mode</strong>先规划再🔥一次性执行。CLAUDE.md沉淀记忆💡告别每次裸奔。顶级开发者正在<strong>训练AI军队</strong>。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kjp3tr35f68vtwc523f7adc6.avif" alt="AI资讯：Boris团队精选的11个Claude Code高效工程工作流可视化全景图" loading="lazy"><br></p></li><li><p><strong>Opus与Codex双模型协作编码实录。</strong> 用户实测🚀<strong>Opus 4.6</strong>擅长<a href="https://x.com/hongming731/status/2028077093524037815" target="_blank" rel="noreferrer">从零到一开发(AI资讯)</a>。堪称综合能力极强的(✧∀✧)<strong>高级工程师</strong>。而<strong>Codex 5.3</strong>专职🔥挑毛病找隐患。两个模型配合💡架构质量双保险。这种<strong>AI编码</strong>组合拳太实用的。</p></li><li><p><strong>Context Mode让Agent上下文省98%。</strong><a href="https://mksg.lu/blog/context-mode" target="_blank" rel="noreferrer">Context Mode(AI资讯)</a>作为MCP服务器🚀横空出世。315KB原始数据压缩至(✧∀✧)仅<strong>5.4KB</strong>。有效会话从30分钟🔥延长至<strong>3小时</strong>。沙箱执行加BM25检索💡双管齐下。配合Cloudflare方案形成完美<strong>优化闭环</strong>。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kjp3v35cf68vtwce7ykp2k52.avif" alt="AI资讯：Context Mode架构图展示Agent输出数据的沙箱压缩流程" loading="lazy"><br></p></li><li><p><strong>Prompt Caching深度拆解缓存命中秘诀。</strong> Claude Code团队🚀把<a href="https://x.com/shao__meng/status/2027905170252959765" target="_blank" rel="noreferrer">缓存命中率(AI资讯)</a>当生产事故级指标。<strong>自动缓存</strong>滑动断点(✧∀✧)彻底解决手动管理痛点。缓存读取成本仅为🔥常规的<strong>10%</strong>。7条黄金准则💡成为Agent开发铁律。压缩复用让成本从$0.09降至**$0.009**。 <br><img src="https://source.hubtoday.app/images/2026/03/news_01kjp3vbn2f68vtwcpz46er4p1.avif" alt="AI资讯：LLM提示缓存KV Cache在多轮对话中的前缀匹配与滑动命中原理图" loading="lazy"><br></p></li><li><p><strong>OpenClaw一键赋予Agent语音和画图能力。</strong> 只要把链接🚀丢进<a href="https://x.com/oran_ge/status/2027919934681190697" target="_blank" rel="noreferrer">OpenClaw(AI资讯)</a>就行。龙虾也能(✧∀✧)开口<strong>说话画图</strong>。<strong>TTS</strong>播客解说视频🔥全部搞定。<a href="https://listenhub.ai/docs/zh/skills" target="_blank" rel="noreferrer">Skills接入指南(AI资讯)</a>极速上手。多模态创作💡门槛降到了零。</p></li><li><p><strong>单线程猪脑子也想并行操控AI。</strong> 网友<a href="https://x.com/ezshine/status/2028159084609048591" target="_blank" rel="noreferrer">自嘲(AI资讯)</a>只能🐷单线程给AI下任务。佩服大佬们(✧∀✧)同时操控<strong>多个龙虾</strong>。<strong>并行调度</strong>🚀才是效率飞升关键。这条吐槽💡引发无数人共鸣。看来多Agent协作确实🔥需要练习。</p></li></ol><hr>`,14)])])}const c=t(s,[["render",o]]);export{b as __pageData,c as default};
